mapper.select:
SELECT id,batch_no AS batchNo,component_id AS componentId,source_receipt_line_id AS sourceReceiptLineId,
       initial_quantity AS initialQuantity,current_quantity AS currentQuantity,unit,unit_cost AS unitCost,
       supplier_lot_no AS supplierLotNo,production_date AS productionDate,expiry_date AS expiryDate,
       location_note AS locationNote,quality_note AS qualityNote,status,create_time AS createTime
FROM lab_inventory_batch WHERE component_id=#{componentId}
ORDER BY create_time DESC,id DESC LIMIT #{pageSize} OFFSET #{offset}

